// SETUP ADMIN
// ════════════════════════════════════════════════════════════════
function SetupAdmin({onDone}) {
  const [pwd,setPwd]=useState(""); const [pwd2,setPwd2]=useState(""); const [err,setErr]=useState(""); const [vis,setVis]=useState(false); const [saving,setSaving]=useState(false);
  const submit = async () => {
    if(pwd.length<8){setErr("كلمة السر يجب أن تحتوي على 8 أحرف على الأقل");return;}
    if(pwd!==pwd2){setErr("كلمتا السر غير متطابقتين");return;}
    setSaving(true);
    await supa.setParam("admin_pwd_hash", simpleHash(pwd));
    await supa.setParam("admin_created", "true");
    onDone();
  };
  return (
    <div style={{minHeight:"100vh",background:`linear-gradient(160deg,${C.forest} 0%,#091a10 100%)`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Cairo','Tajawal',sans-serif",padding:24,direction:"rtl"}}>
      <div style={{width:"100%",maxWidth:480,zIndex:2}}>
        <div style={{textAlign:"center",marginBottom:36}}>
          <img src={apsvtLogo} alt="APSVT" style={{width:80,height:80,borderRadius:"50%",objectFit:"contain",background:"rgba(255,255,255,0.92)",padding:6,boxShadow:"0 12px 40px rgba(74,158,104,.45)",marginBottom:18}}/>
          <h1 style={{color:C.mist,fontSize:24,fontWeight:"normal",margin:"0 0 6px"}}>جمعية أساتذة علوم الحياة والأرض</h1>
          <p style={{color:"#4a7a60",fontSize:12,margin:0,letterSpacing:2,textTransform:"uppercase"}}>APSVT — الإعداد الأولي</p>
        </div>
        <div style={{background:"rgba(255,255,255,.04)",backdropFilter:"blur(24px)",border:"1px solid rgba(180,220,200,.15)",borderRadius:20,padding:"40px 44px",boxShadow:"0 40px 100px rgba(0,0,0,.5)"}}>
          <div style={{background:"rgba(74,158,104,.1)",border:"1px solid rgba(74,158,104,.25)",borderRadius:12,padding:"14px 18px",marginBottom:28,display:"flex",gap:12,alignItems:"flex-start"}}>
            <span style={{fontSize:20}}>🔐</span>
            <div><div style={{color:C.moss,fontSize:14,marginBottom:4}}>إنشاء حساب مدير النظام</div>
            <div style={{color:"#4a7a60",fontSize:12,lineHeight:1.6}}>ستتمكن بواسطة هذه الكلمة السرية من إدارة الأعضاء وصلاحياتهم والخزينة.</div></div>
          </div>
          {[["كلمة سر المدير",pwd,setPwd],["تأكيد كلمة السر",pwd2,setPwd2]].map(([lbl,val,set],i)=>(
            <div key={i} style={{marginBottom:18}}>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:8,fontFamily:"sans-serif"}}>{lbl}</label>
              <div style={{position:"relative"}}>
                <input type={vis?"text":"password"} value={val} onChange={e=>{set(e.target.value);setErr("");}} onKeyDown={e=>e.key==="Enter"&&i===1&&submit()}
                  style={{width:"100%",padding:"13px 44px 13px 16px",background:"rgba(255,255,255,.06)",border:`1.5px solid ${err?"#c05050":"rgba(180,220,200,.2)"}`,borderRadius:10,color:C.mist,fontSize:15,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
                {i===0&&<button onClick={()=>setVis(!vis)} style={{position:"absolute",left:14,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",color:"#5a8070",cursor:"pointer",fontSize:18}}>{vis?"🙈":"👁"}</button>}
              </div>
            </div>
          ))}
          {err&&<p style={{color:"#e07070",fontSize:13,margin:"-4px 0 14px",fontFamily:"sans-serif"}}>⚠️ {err}</p>}
          <button onClick={submit} disabled={saving}
            style={{width:"100%",padding:"15px",background:"linear-gradient(135deg,#2e6b47,#4a9e68)",border:"none",borderRadius:12,color:"#e8f5ec",fontSize:16,cursor:"pointer",fontFamily:"'Cairo',sans-serif",boxShadow:"0 8px 24px rgba(46,107,71,.4)"}}>
            {saving?"جاري الحفظ...":"إنشاء حساب المدير"}
          </button>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// CHANGEMENT MOT DE PASSE (1er accès)
// ════════════════════════════════════════════════════════════════
function ChangerMotDePasse({session, onDone}) {
  const [pwd,setPwd]=useState(""); const [pwd2,setPwd2]=useState(""); const [err,setErr]=useState(""); const [saving,setSaving]=useState(false);
  const submit = async () => {
    if(pwd.length<8){setErr("8 أحرف على الأقل");return;}
    if(pwd!==pwd2){setErr("كلمتا السر غير متطابقتين");return;}
    setSaving(true);
    await supa.updateMembre(session.id,{pwd_hash:simpleHash(pwd),premier_acces:false});
    onDone({...session,premier_acces:false});
  };
  return (
    <div style={{minHeight:"100vh",background:`linear-gradient(160deg,${C.forest} 0%,#091a10 100%)`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Cairo','Tajawal',sans-serif",padding:24,direction:"rtl"}}>
      <div style={{width:"100%",maxWidth:440}}>
        <div style={{textAlign:"center",marginBottom:28}}>
          <img src={apsvtLogo} alt="APSVT" style={{width:68,height:68,borderRadius:"50%",objectFit:"contain",background:"rgba(255,255,255,0.92)",padding:4,marginBottom:14}}/>
          <h2 style={{color:C.mist,fontWeight:"normal",margin:"0 0 6px"}}>مرحباً {session.prenom} {session.nom}</h2>
          <p style={{color:"#4a7a60",fontSize:13,margin:0}}>يرجى تغيير كلمة السر عند أول دخول</p>
        </div>
        <div style={{background:"rgba(255,255,255,.04)",border:"1px solid rgba(180,220,200,.15)",borderRadius:20,padding:"32px 36px"}}>
          <div style={{background:"rgba(255,183,0,.1)",border:"1px solid rgba(255,183,0,.3)",borderRadius:10,padding:"12px 16px",marginBottom:22,fontSize:13,color:"#c8a000",fontFamily:"sans-serif"}}>
            🔑 هذه أول مرة تسجّل فيها دخولك. يجب عليك تغيير كلمة السر للمتابعة.
          </div>
          {[["كلمة السر الجديدة",pwd,setPwd],["تأكيد كلمة السر",pwd2,setPwd2]].map(([lbl,val,set],i)=>(
            <div key={i} style={{marginBottom:14}}>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,marginBottom:6,fontFamily:"sans-serif"}}>{lbl}</label>
              <input type="password" value={val} onChange={e=>{set(e.target.value);setErr("");}}
                style={{width:"100%",padding:"12px 16px",background:"rgba(255,255,255,.06)",border:`1.5px solid rgba(180,220,200,.2)`,borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
            </div>
          ))}
          {err&&<p style={{color:"#e07070",fontSize:13,margin:"0 0 12px",fontFamily:"sans-serif"}}>⚠️ {err}</p>}
          <button onClick={submit} disabled={saving}
            style={{width:"100%",padding:"13px",background:"linear-gradient(135deg,#2e6b47,#4a9e68)",border:"none",borderRadius:11,color:"#e8f5ec",fontSize:15,cursor:"pointer",fontFamily:"'Cairo',sans-serif"}}>
            {saving?"جاري الحفظ...":"تأكيد كلمة السر الجديدة"}
          </button>
        </div>
      </div>
    </div>
  );
}

