      if(error){toast_("خطأ: "+error.message,"error");return;}
      await supa.updateDemande(d.id,{statut:"confirme",date_traitement:today()});
      setDemandes(p=>p.map(x=>x.id===d.id?{...x,statut:"confirme"}:x));
      const nouveauMembre = await supa.getMembres();
      setMembres(nouveauMembre);
