            {can.saisirCR&&<Btn variant="ghost" onClick={()=>{setForm({...selected});setVue("form");}}>✏️ تعديل</Btn>}
            {can.saisirCR&&<Btn variant="danger" onClick={()=>deleteCR(selected.id)}>🗑 حذف</Btn>}
