  async deleteAnnonce(id) { await supabase.from('annonces').delete().eq('id', id); },

  // COMPTES RENDUS
  async getComptesRendus() { const { data } = await supabase.from('comptes_rendus').select('*').order('date_evenement', { ascending: false }); return data ?? []; },
  async addCompteRendu(cr) { const { data, error } = await supabase.from('comptes_rendus').insert([cr]).select().single(); return { data, error }; },
  async updateCompteRendu(id, changes) { await supabase.from('comptes_rendus').update(changes).eq('id', id); },
  async deleteCompteRendu(id) { await supabase.from('comptes_rendus').delete().eq('id', id); },

  // STORAGE — pièces jointes
  async uploadFichier(file, path) {
    const { supabase: sb } = await import('./supabase');
    const { data, error } = await supabase.storage.from('apsvt-documents').upload(path, file, { upsert: true });
    if (error) return { url: null, error };
    const { data: urlData } = supabase.storage.from('apsvt-documents').getPublicUrl(path);
    return { url: urlData.publicUrl, error: null };
  },
